import * as T from './vendor/three.module.js';
const coin=new T.CylinderGeometry(.22,.22,.08,16),rim=new T.TorusGeometry(.225,.025,5,20),gold=new T.MeshStandardMaterial({color:0xe8bd59,metalness:.6,roughness:.3,emissive:0xb57e24,emissiveIntensity:.3}),ink=new T.MeshStandardMaterial({color:0x47371e,roughness:.6});
const stripeGeo=new T.BoxGeometry(.05,.23,.012),crossGeo=new T.BoxGeometry(.19,.05,.012);
export function createChoiceToken(id,position){const mesh=new T.Group();mesh.name='attachment-choice-token';const body=new T.Mesh(coin,gold);body.rotation.x=Math.PI/2;mesh.add(body);const ring=new T.Mesh(rim,gold);ring.position.z=.047;mesh.add(ring);for(const side of [-1,1]){const stripe=new T.Mesh(stripeGeo,ink);stripe.position.z=side*.049;mesh.add(stripe);const cross=new T.Mesh(crossGeo,ink);cross.position.z=side*.05;mesh.add(cross);}mesh.position.copy(position);mesh.position.y+=.48;return{id,kind:'token',x:position.x,y:position.y,z:position.z,mesh,collected:false};}
